operation.add:
// Tree Catalog Module
$data['tree_catalog_modules'] = array();
$this->load->model('setting/module');
$modules = $this->model_setting_module->getModulesByCode('tree_catalog');
foreach ($modules as $module) {
    $setting_info = $this->model_setting_module->getModule($module['module_id']);
    if ($setting_info && $setting_info['status']) {
        $data['tree_catalog_modules'][] = $setting_info;
    }
}

{% if tree_catalog_modules is defined %}
{% for tree_module in tree_catalog_modules %}
{{ tree_module }}
{% endfor %}
{% endif %}
